vice id. Must not contain '.' so the ParamRef path track.device.<deviceId>.<paramKey> stays parseable.","minLength":1,"pattern":"^[A-Za-z0-9_-]+$","type":"string"},"key":{"description":"An instrument parameter key from DEVICE_PARAM_KEYS \u2014 the SAME token the ParamRef path track.device.<deviceId>.<paramKey> already carries, so a value authored here and a lane automating it name the parameter identically. Which keys a given kind honours is deliberately NOT validated: apply.rs runs on replay, so tightening the (kind, key) pairing later would break replay of a project that authored a key its kind ignores (a drum rack ignores 'waveform'; every kind but 'synth' ignores it).","minLength":1,"pattern":"^[A-Za-z0-9_-]+$","type":"string"},"trackId":{"description":"Id of the track the instrument sits on.","minLength":1,"type":"string"},"value":{"description":"Parameter value. Journaled as a Num, so the integer/float SHAPE round-trips exactly.","type":"number"}},"required":["trackId","deviceId","key","value"],"type":"object"},"device.remove":{"additionalProperties":false,"properties":{"deviceId":{"description":"Opaque device id. Must not contain '.' so the ParamRef path track.device.<deviceId>.<paramKey> stays parseable.","minLength":1,"pattern":"^[A-Za-z0-9_-]+$","type":"string"},"trackId":{"description":"Id of the track the instrument sits on.","minLength":1,"type":"string"}},"required":["trackId","deviceId"],"type":"object"},"device.zone.add":{"additionalProperties":false,"properties":{"deviceId":{"description":"Opaque device id. Must not contain '.' so the ParamRef path track.device.<deviceId>.<paramKey> stays parseable.","minLength":1,"pattern":"^[A-Za-z0-9_-]+$","type":"string"},"gainDb":{"description":"Optional zone/pad gain in dB. Default 0, which is unity.","type":"number"},"hiPitch":{"description":"Highest MIDI key the zone covers, 0 to 127. Must be >= loPitch, and must EQUAL loPitch on a 'drum' device, because a pad is one key.","maximum":127,"minimum":0,"type":"integer"},"loPitch":{"description":"Lowest MIDI key the zone covers, 0 to 127.","maximum":127,"minimum":0,"type":"integer"},"pan":{"description":"Optional pad pan, -1 is hard left and 1 is hard right; default 0 is centre. Honoured by kind 'drum'; IGNORED by 'sampler', which is a pitched instrument sitting on the track's own pan.","maximum":1,"minimum":-1,"type":"number"},"rootPitch":{"description":"The MIDI note the recording sounds at, 0 to 127; a sampler reads at 2^((pitch-rootPitch)/12). Ignored by kind 'drum', which does not pitch-track.","maximum":127,"minimum":0,"type":"integer"},"sourceId":{"description":"Content-addressed asset id \u2014 the SAME registry clip.place's assetHash names. Resolved render-side through the same loaded-source map, with the same loud 'references unloaded source' failure.","minLength":1,"type":"string"},"trackId":{"description":"Id of the track the sampler/drum device sits on.","minLength":1,"type":"string"},"zoneId":{"description":"Opaque, stable zone id. Identity for edit and undo.","minLength":1,"type":"string"}},"required":["trackId","deviceId","zoneId","sourceId","rootPitch","loPitch","hiPitch"],"type":"object"},"device.zone.remove":{"additionalProperties":false,"properties":{"deviceId":{"description":"Opaque device id. Must not contain '.' so the ParamRef path track.device.<deviceId>.<paramKey> stays parseable.","minLength":1,"pattern":"^[A-Za-z0-9_-]+$","type":"string"},"trackId":{"description":"Id of the track the sampler/drum device sits on.","minLength":1,"type":"string"},"zoneId":{"description":"Opaque, stable zone id.","minLength":1,"type":"string"}},"required":["trackId","deviceId","zoneId"],"type":"object"},"export.manifest":{"additionalProperties":false,"properties":{"outputPath":{"description":"Filesystem path to write the provenance manifest JSON to. Manage tier: this writes outside the project, so the tool also needs confirm: true. Use the studio_manifest READ tool if you only want to look at it.","minLength":1,"type