alProperties":false,"properties":{"fxId":{"description":"Opaque fx id, unique within this host's chain. Must not contain '.' so the ParamRef paths track.fx.<fxId>.<paramKey>, bus.<nodeId>.fx.<fxId>.<paramKey> and master.fx.<fxId>.<paramKey> stay parseable.","minLength":1,"pattern":"^[A-Za-z0-9_-]+$","type":"string"},"kind":{"description":"Which effect to insert, from the CLOSED E5 vocabulary: 'eq', 'compressor', 'gate', 'delay', 'reverb', 'saturator', 'chorus', 'utility' or 'limiter'. An unknown kind fails loudly at the contract boundary rather than building a silent no-op node.","enum":["eq","compressor","gate","delay","reverb","saturator","chorus","utility","limiter"],"type":"string"},"target":{"description":"The fx HOST, as a NodeRef: 'track.<id>', 'bus.<id>' or 'master'. Master is addressable because a master-bus effect chain is table stakes for parity and falls out of the NodeRef grammar for free.","pattern":"^(master|(track|bus)\\.[A-Za-z0-9_-]+)$","type":"string"}},"required":["target","fxId","kind"],"type":"object"},"fx.move":{"additionalProperties":false,"properties":{"fxId":{"description":"Opaque fx id, unique within this host's chain. Must not contain '.' so the ParamRef paths track.fx.<fxId>.<paramKey>, bus.<nodeId>.fx.<fxId>.<paramKey> and master.fx.<fxId>.<paramKey> stay parseable.","minLength":1,"pattern":"^[A-Za-z0-9_-]+$","type":"string"},"index":{"description":"New 0-based position in the chain. Chain order IS processing order.","minimum":0,"type":"integer"},"target":{"description":"The fx HOST, as a NodeRef: 'track.<id>', 'bus.<id>' or 'master'. Master is addressable because a master-bus effect chain is table stakes for parity and falls out of the NodeRef grammar for free.","pattern":"^(master|(track|bus)\\.[A-Za-z0-9_-]+)$","type":"string"}},"required":["target","fxId","index"],"type":"object"},"fx.param.clear":{"additionalProperties":false,"properties":{"fxId":{"description":"Opaque fx id, unique within this host's chain. Must not contain '.' so