escription":"Parameter value. Journaled as a Num, so the integer/float SHAPE round-trips exactly.","type":"number"}},"required":["target","fxId","key","value"],"type":"object"},"fx.remove":{"additionalProperties":false,"properties":{"fxId":{"description":"Opaque fx id, unique within this host's chain. Must not contain '.' so the ParamRef paths track.fx.<fxId>.<paramKey>, bus.<nodeId>.fx.<fxId>.<paramKey> and master.fx.<fxId>.<paramKey> stay parseable.","minLength":1,"pattern":"^[A-Za-z0-9_-]+$","type":"string"},"target":{"description":"The fx HOST, as a NodeRef: 'track.<id>', 'bus.<id>' or 'master'. Master is addressable because a master-bus effect chain is table stakes for parity and falls out of the NodeRef grammar for free.","pattern":"^(master|(track|bus)\\.[A-Za-z0-9_-]+)$","type":"string"}},"required":["target","fxId"],"type":"object"},"fx.sidechain.clear":{"additionalProperties":false,"properties":{"fxId":{"description":"Opaque fx id, unique within this host's chain. Must not contain '.' so the ParamRef paths track.fx.<fxId>.<paramKey>, bus.<nodeId>.fx.<fxId>.<paramKey> and master.fx.<fxId>.<paramKey> stay parseable.","minLength":1,"pattern":"^[A-Za-z0-9_-]+$","type":"string"},"target":{"description":"The fx HOST, as a NodeRef: 'track.<id>', 'bus.<id>' or 'master'. Master is addressable because a master-bus effect chain is table stakes for parity and falls out of the NodeRef grammar for free.","pattern":"^(master|(track|bus)\\.[A-Za-z0-9_-]+)$","type":"string"}},"required":["target","fxId"],"type":"object"},"fx.sidechain.set":{"additionalProperties":false,"properties":{"fxId":{"description":"Opaque fx id, unique within this host's chain. Must not contain '.' so the ParamRef paths track.fx.<fxId>.<paramKey>, bus.<nodeId>.fx.<fxId>.<paramKey> and master.fx.<fxId>.<paramKey> stay parseable.","minLength":1,"pattern":"^[A-Za-z0-9_-]+$","type":"string"},"source":{"description":"The KEY source, as a NodeRef: 'track.<id>' or 'bus.<id>'. Master is the sink and can never be a key source.","pattern":"^(master|(track|bus)\\.[A-Za-z0-9_-]+)$","type":"string"},"target":{"description":"The fx HOST, as a NodeRef: 'track.<id>', 'bus.<id>' or 'master'. Master is addressable because a master-bus effect chain is table stakes for parity and falls out of the NodeRef grammar for free.","pattern":"^(master|(track|bus)\\.[A-Za-z0-9_-]+)$","type":"string"}},"required":["target","fxId","source"],"type":"object"},"gen.autocomplete":{"additionalProperties":false,"properties":{"clipId":{"description":"Id of the partial-mix clip to fill instruments in around. Must exist.","minLength":1,"type":"string"},"request":{"description":"The Gen Protocol 'autocomplete' request body; free-form here, with the full shape in gen-protocol.v1.yaml (see gen-protocol-mapping.md).","type":"object"},"requestId":{"description":"Caller-minted ULID naming this job: Crockford base32, 26 characters, first character 0-7. Mint a fresh one per request.","pattern":"^[0-7][0-9A-HJKMNP-TV-Z]{25}$","type":"string"}},"required":["requestId","clipId","request"],"type":"object"},"gen.cancel":{"additionalProperties":false,"properties":{"requestId":{"description":"The requestId of the job to cancel: Crockford base32 ULID, 26 characters, first character 0-7. See this command's own note \u2014 the shipped backend cancel is global, not per-request.","pattern":"^[0-7][0-9A-HJKMNP-TV-Z]{25}$","type":"string"}},"required":["requestId"],"type":"object"},"gen.cover":{"additionalProperties":false,"properties":{"referenceClipId":{"description":"Id of the clip whose performance is re-styled. Must exist.","minLength":1,"type":"string"},"request":{"description":"The Gen Protocol 'cover' request body, including coverStrength; the full shape is in gen-protocol.v1.yaml (see gen-protocol-mapping.md).","type":"object"},"requestId":{"description":"Caller-minted ULID naming this job: Crockford base32, 26 characters, first character 0-7. Mint a fresh one per request.","pattern":"^[0-7][0-9A-HJKMNP-TV-Z]{25}$","type":"string"}},"required":["requestId","referenceClipId","request"],"type":"object"},"gen.extend":{"additionalProperties":false,"properties":{"addedDurationSeconds":{"description":"How much new audio to append, in SECONDS (not ticks), greater than 0.","exclusiveMinimum":0,"type":"number"},"clipId":{"description":"Id of the clip whose audio is continued. Must exist.","minLength":1,"type":"string"},"request":{"description":"The Gen Protocol 'extend' request body; free-form here, with the full shape in gen-protocol.v1.yaml (see gen-protocol-mapping.md).","type":"object"},"requestId":{"description":"Caller-minted ULID naming this job: Crockford base32, 26 characters, first character 0-7. Mint a fresh one per request.","pattern":"^[0-7][0-9A-HJKMNP-TV-Z]{25}$","type":"string"}},"required":["requestId","clipId","addedDurationSeconds","request"],"type":"object"},"gen.finalize":{"additionalProperties":false,"properties":{"draftTakeId":{"description":"The committed draft take being re-rendered at higher quality.","minLength":1,"type":"string"},"request":{"description":"The same request body as the revise op that produced draftTakeId \u2014 identical region, instruction and scope. Only the model/steps rung changes. See gen-protocol-mapping.md.","type":"object"},"requestId":{"description":"Caller-minted ULID naming this re-render job: Crockford base32, 26 characters, first character 0-7. Distinct from the requestId that produced draftTakeId.","pattern":"^[0-7][0-9A-HJKMNP-TV-Z]{25}$","type":"string"},"targetQualityRung":{"description":"Quality rung to re-render at: 'draft' (acestep-v15-turbo, 8 steps), 'standard' (acestep-v15-quality) or 'full' (acestep-v15-base, 50 steps). finalize always targets a rung above the draft's own.","enum":["draft","standard","full"],"type":"string"}},"required":["requestId","draftTakeId","targetQualityRung","request"],"type":"object"},"gen.landed":{"additionalProperties":false,"properties":{"assetHashes":{"additionalProperties":{"pattern":"^[0-9a-f]{64}$","type":"string"},"description":"The audio this job produced, keyed by 'mix' for a single-file take or by stem name ('vocals', 'drums', 'bass', 'other') for a per-stem take. Each value is a 64-character lowercase blake3 hex hash.","minProperties":1,"type":"object"},"engineIdentity":{"additionalProperties":false,"description":"Which engine produced the audio, for lineage and the AI-disclosure manifest: model and device are required, steps and seed are optional and present only when the backend reported them.","properties":{"device":{"description":"Where the job ran: 'mlx', 'mps', 'cuda', 'cpu' or 'remote'.","enum":["mlx","mps","cuda","cpu","remote"],"type":"string"},"model":{"description":"Model identifier as the backend reports it, e.g. 'acestep-v15-turbo'. Non-empty.","minLength":1,"type":"string"},"seed":{"description":"Optional RNG seed the run used; any integer, negative included. It is what makes a retake reproducible. Omitted when the backend does not report one.","type":"integer"},"steps":{"description":"Optional diffusion step count, 1 or more. Omitted when the backend does not report it.","minimum":1,"type":"integer"}},"required":["model","device"],"type":"object"},"latencySeconds":{"description":"Optional wall-clock duration of the job in seconds, 0 or more. Omitted when it was not measured.","minimum":0,"type":"number"},"requestId":{"description":"Matches the requestId of the gen.* command that started this job.","pattern":"^[0-7][0-9A-HJKMNP-TV-Z]{25}$","type":"string"},"sourceCommand":{"description":"Dotted catalog name of the gen.* command that started this job, e.g. 'gen.revise'. Lineage and the export manifest read it to say which operation produced the take.","pattern":"^[a-z][a-zA-Z0-9]*(\\.[a-z][a-zA-Z0-9]*)+$","type":"string"},"takeId":{"description":"Id of the candidate take this job produced. take.promote / take.discard / take.purge address it by this id.","minLength":1,"type":"string"}},"required":["requestId","sourceCommand","takeId","assetHashes","engineIdentity"],"type":"object"},"gen.layer":{"additionalProperties":false,"properties":{"contextClipId":{"description":"Optional id of an existing clip to fit the new stem against harmonically and rhythmically. Omitted generates without existing-audio context.","minLength":1,"type":"string"},"instruction":{"description":"What the new stem should be, e.g. 'bass' or 'sax lead' \u2014 matched verbatim against ace_generator.generate_lego's instruction. Non-empty.","minLength":1,"type":"string"},"request":{"description":"The Gen Protocol 'layer' request body; free-form here, with the full shape in gen-protocol.v1.yaml (see gen-protocol-mapping.md).","type":"object"},"requestId":{"description":"Caller-minted ULID naming this job: Crockford base32, 26 characters, first character 0-7. Mint a fresh one per request.","pattern":"^[0-7][0-9A-HJKMNP-TV-Z]{25}$","type":"string"},"targetTrackId":{"description":"Id of the track the new stem is destined for; it must already exist.","minLength":1,"type":"string"}},"required":["requestId","targetTrackId","instruction","request"],"type":"object"},"gen.retake":{"additionalProperties":false,"properties":{"request":{"description":"The Gen Protocol 'retake' request body: the same prompt as sourceTakeId with a fresh seed and no instruction changes. Full shape in gen-protocol.v1.yaml (see gen-protocol-mapping.md).","type":"object"},"requestId":{"description":"Caller-minted ULID naming this job: Crockford base32, 26 characters, first character 0-7. Mint a fresh one per request.","pattern":"^[0-7][0-9A-HJKMNP-TV-Z]{25}$","type":"string"},"sourceTakeId":{"description":"Id of the existing take to re-roll: same prompt, fresh seed. Must be a take this project knows.","minLength":1,"type":"string"}},"required":["requestId","sourceTakeId","request"],"type":"object"},"gen.revise":{"additionalProperties":false,"properties":{"clipId":{"description":"Id of the clip whose region is repainted. Must exist.","minLength":1,"type":"string"},"regionEndTicks":{"description":"Region end, in absolute timeline ticks from 0 (PPQ 960: 960 ticks is a quarter note, 3840 is one 4/4 bar). Must be strictly after regionStartTicks.","minimum":0,"type":"integer"},"regionStartTicks":{"description":"Region start, in absolute timeline ticks from 0 (PPQ 960: 960 ticks is a quarter note, 3840 is one 4/4 bar). Must be strictly before regionEndTicks \u2014 an empty or inverted region is refused.","minimum":0,"type":"integer"},"request":{"description":"The rest of the Gen Protocol 'revise' request. instruction is required and variants optional; the full shape is in gen-protocol.v1.yaml (see gen-protocol-mapping.md).","properties":{"instruction":{"description":"What to change, in words, e.g. 'make the drums busier'. Non-empty.","minLength":1,"type":"string"},"variants":{"default":1,"description":"How many alternative takes to ask for, 1 to 5. Default 1.","maximum":5,"minimum":1,"type":"integer"}},"required":["instruction"],"type":"object"},"requestId":{"description":"Caller-minted ULID naming this job: Crockford base32, 26 characters, first character 0-7. Mint a fresh one per request.","pattern":"^[0-7][0-9A-HJKMNP-TV-Z]{25}$","type":"string"},"scope":{"description":"What the repaint touches: the scalar 'all-stems', or one stem name, or an array of stem names from 'vocals', 'drums', 'bass' and 'other'. 'all-stems' is valid only as a scalar; an array selects those stems and null-preserves the rest.","oneOf":[{"enum":["all-stems","vocals","drums","bass","other"],"type":"string"},{"items":{"enum":["vocals","drums","bass","other"],"type":"string"},"minItems":1,"type":"array","uniqueItems":true}]}},"required":["requestId","clipId","regionStartTicks","regionEndTicks","scope","request"],"type":"object"},"gen.separate":{"additionalProperties":false,"properties":{"clipId":{"description":"Id of the clip to split into stems. Must exist.","minLength":1,"type":"string"},"engine":{"description":"Which separator to run: 'demucs' (htdemucs 4-stem separation, the default separator) or 'ace-extract' (ACE-Step generative extraction, which lineage labels GENERATIVE rather than separated).","enum":["demucs","ace-extract"],"type":"string"},"requestId":{"description":"Caller-minted ULID naming this job: Crockford base32, 26 characters, first character 0-7. Mint a fresh one per request.","pattern":"^[0-7][0-9A-HJKMNP-TV-Z]{25}$","type":"string"}},"required":["requestId","clipId","engine"],"type":"object"},"gen.song":{"additionalProperties":false,"properties":{"insertAtTicks":{"description":"Where the result is meant to land, in absolute timeline ticks from 0 (PPQ 960: 960 ticks is a quarter note, 3840 is one 4/4 bar). Recorded on the request record; the actual placement happens at take.promote.","minimum":0,"type":"integer"},"request":{"description":"The rest of the Gen Protocol 'generate' request. caption is the one field this schema pins; the full shape is in gen-protocol.v1.yaml (see gen-protocol-mapping.md).","properties":{"caption":{"description":"The text2music prompt, e.g. 'dreamy lo-fi hip hop with rhodes'. Non-empty.","minLength":1,"type":"string"}},"required":["caption"],"type":"object"},"requestId":{"description":"Caller-minted ULID naming this job: Crockford base32, 26 characters, first character 0-7. gen.landed quotes it back and gen.cancel takes it. Mint a fresh one per request.","pattern":"^[0-7][0-9A-HJKMNP-TV-Z]{25}$","type":"string"},"trackId":{"description":"Id of the track the result is destined for; it must already exist. Nothing is placed by this command \u2014 take.promote does that once the take lands.","minLength":1,"type":"string"}},"required":["requestId","trackId","insertAtTicks","request"],"type":"object"},"import.audio":{"additionalProperties":false,"properties":{"clipId":{"description":"Optional caller-minted id for the placed clip. Omitted, the host mints one and returns it in the result.","minLength":1,"type":"string"},"conform":{"default":false,"description":"Declared as 'time-stretch the imported audio to the project tempo on import'. NOT IMPLEMENTED and silently ignored: the audio is imported at its own length. Default false. To fit it to the tempo, place it and then call clip.warp.set.","type":"boolean"},"separate":{"default":false,"description":"Declared as 'run htdemucs on import and place stems as separate tracks'. NOT IMPLEMENTED and silently ignored: the file is imported and placed as one ordinary clip. Use studio_open_in_studio for separation, or import.stems with stems you separated yourself. Default false.","type":"boolean"},"sourcePath":{"description":"Filesystem path of the audio file to bring in. It is COPIED content-addressed into the package's audio/ directory, so the original may move afterwards.","minLength":1,"type":"string"},"startTicks":{"default":0,"description":"Optional clip start on the target track, in absolute timeline ticks from 0 (PPQ 960: 960 ticks is a quarter note, 3840 is one 4/4 bar). Default 0.","minimum":0,"type":"integer"},"targetTrackId":{"description":"Id of the existing track the imported clip is placed on.","minLength":1,"type":"string"}},"required":["sourcePath","targetTrackId"],"type":"object"},"import.stems":{"additionalProperties":false,"properties":{"groupName":{"description":"Optional label for the imported group, echoed back in the result. Defaults to 'Imported stems'.","minLength":1,"type":"string"},"sourceDir":{"description":"Filesystem path of a directory of stem files. Every audio file directly in it is copied content-addressed into audio/ and placed on its own track.","minLength":1,"type":"string"},"startTicks":{"default":0,"description":"Optional common start for every stem, in absolute timeline ticks from 0 (PPQ 960: 960 ticks is a quarter note, 3840 is one 4/4 bar). Default 0, which keeps the stems aligned with each other.","minimum":0,"type":"integer"},"targetTrackId":{"description":"Id of the FIRST track of the group; the remaining stems land on tracks created after it.","minLength":1,"type":"string"}},"required":["sourceDir","targetTrackId"],"type":"object"},"marker.remove":{"additionalProperties":false,"properties":{"markerId":{"description":"Id of an existing marker. Removing an id that is not there is a typed error, not a silent no-op.","minLength":1,"type":"string"}},"required":["markerId"],"type":"object"},"marker.set":{"additionalProperties":false,"properties":{"color":{"description":"Optional swatch, '#RRGGBB' hex with six digits and no alpha (e.g. '#FF8800'). Omitted leaves the marker with no explicit colour.","pattern":"^#[0-9A-Fa-f]{6}$","type":"string"},"label":{"description":"Text drawn on the marker in the ruler, e.g. 'Solo starts'. Non-empty.","minLength":1,"type":"string"},"markerId":{"description":"Caller-minted, stable id for the marker; the engine never mints one. A fresh id CREATES a marker, an existing id UPDATES it (this command is an upsert).","minLength":1,"type":"string"},"positionTicks":{"description":"Marker position, in absolute timeline ticks from 0 (PPQ 960: 960 ticks is a quarter note, 3840 is one 4/4 bar).","minimum":0,"type":"integer"}},"required":["markerId","positionTicks","label"],"type":"object"},"midi.binding.clear":{"additionalProperties":false,"properties":{"control":{"additionalProperties":false,"description":"The exact control coordinates of the binding to drop \u2014 the same type/channel/number shape midi.binding.set matched on. There are no wildcards: a binding is cleared by naming it exactly.","properties":{"channel":{"description":"MIDI channel the binding matched, 0-BASED: 0 to 15.","maximum":15,"minimum":0,"type":"integer"},"number":{"description":"Note or CC number the binding matched, 0 to 127. Omitted for pitchBend, which is channel-wide.","maximum":127,"minimum":0,"type":"integer"},"type":{"description":"Which MIDI message class the binding matched: 'noteOn', 'noteOff', 'controlChange' or 'pitchBend'.","enum":["noteOn","noteOff","controlChange","pitchBend"],"type":"string"}},"required":["type","channel"],"type":"object"},"device":{"description":"Reported MIDI port name whose user overlay map holds the binding, e.g. 'USB MIDI Interface'.","minLength":1,"type":"string"}},"required":["device","control"],"type":"object"},"midi.binding.set":{"additionalProperties":false,"properties":{"control":{"additionalProperties":false,"description":"Optional explicit control coordinates (type, channel, and number for note/CC). Omitted uses the learn session's captured control.","properties":{"channel":{"description":"MIDI channel to match, 0-BASED: 0 to 15. Channel 1 on the hardware is 0 here.","maximum":15,"minimum":0,"type":"integer"},"number":{"description":"Note or CC number to match, 0 to 127. Optional, and omitted for pitchBend, which is channel-wide.","maximum":127,"minimum":0,"type":"integer"},"type":{"description":"Which MIDI message class the binding matches: 'noteOn', 'noteOff', 'controlChange' or 'pitchBend'.","enum":["noteOn","noteOff","controlChange","pitchBend"],"type":"string"}},"required":["type","channel"],"type":"object"},"device":{"description":"Optional port name whose resolved map takes the binding. Omitted uses the learn session's captured device.","minLength":1,"type":"string"},"enabled":{"default":true,"description":"Whether the binding fires at all. Default true; false keeps it on file without it acting.","type":"boolean"},"label":{"description":"Optional human-readable name for the binding, shown in MIDI settings. Omitted leaves it unlabelled.","type":"string"},"target":{"additionalProperties":false,"description":"What firing this control DOES. kind 'command' submits a catalog command (name + a params template that may carry the '$value' and '$track:N' placeholders), 'builtin' runs a named built-in action, 'sterling' queues instruction text for the Sterling copilot.","properties":{"instruction":{"description":"Instruction text queued for the Sterling copilot. Required for kind 'sterling', optional and ignored otherwise.","minLength":1,"type":"string"},"kind":{"description":"Which target family this is: 'command' (a catalog command by name), 'builtin' (a named built-in action) or 'sterling' (instruction text queued for the copilot).","enum":["command","builtin","sterling"],"type":"string"},"name":{"description":"The action to run: with kind 'command' a catalog command name, with kind 'builtin' one of the built-in action names. Optional for kind 'sterling', which uses instruction instead.","minLength":1,"type":"string"},"params":{"description":"Optional params template for kind 'command'. May carry the '$value' placeholder (the mapped control value) and '$track:N' (the Nth track's id).","type":"object"}},"required":["kind"],"type":"object"},"valueMap":{"additionalProperties":false,"description":"Optional scaling from the controller's raw reading to the value the target receives. Omitted, the raw is normalized to 0..1 and handed over as-is.","properties":{"curve":{"default":"linear","description":"How input maps onto output between the two ends: 'linear', 'exponential' or 'logarithmic'. Default 'linear'.","enum":["linear","exponential","logarithmic"],"type":"string"},"inputMax":{"default":127,"description":"Raw controller value treated as the high end, 0 to 127. Default 127.","maximum":127,"minimum":0,"type":"integer"},"inputMin":{"default":0,"description":"Raw controller value treated as the low end, 0 to 127. Default 0.","maximum":127,"minimum":0,"type":"integer"},"outputMax":{"default":1,"description":"Value produced at inputMax, in the TARGET parameter's own units. Default 1.","type":"number"},"outputMin":{"default":0,"description":"Value produced at inputMin, in the TARGET parameter's own units (dB for a gain, -1..1 for a pan). Default 0.","type":"number"}},"type":"object"}},"required":["target"],"type":"object"},"midi.device.select":{"additionalProperties":false,"properties":{"device":{"description":"Reported port name, e.g. 'USB MIDI Interface'.","minLength":1,"type":"string"},"map":{"description":"Optional map key (file stem or map name) to pin to this port, 'none' to leave the port unmapped, or 'auto' to go back to pattern auto-detect. Omitted leaves the current selection alone.","minLength":1,"type":"string"}},"required":["device"],"type":"object"},"midi.learn.start":{"additionalProperties":false,"properties":{"device":{"description":"Optional port name to scope capture to, e.g. 'USB MIDI Interface'. Omitted takes the first control from any device.","minLength":1,"type":"string"}},"type":"object"},"midi.learn.stop":{"additionalProperties":false,"properties":{},"type":"object"},"midi.map.export":{"additionalProperties":false,"properties":{"map":{"description":"Map key (file stem or map name).","minLength":1,"type":"string"},"outputPath":{"description":"Filesystem path to write the map file to. Manage tier: this writes outside the app's own directories, so the tool also needs confirm: true.","minLength":1,"type":"string"}},"required":["map","outputPath"],"type":"object"},"midi.map.import":{"additionalProperties":false,"properties":{"overwrite":{"default":false,"description":"Optional. true replaces an existing user map with the same file name; false (the default) refuses rather than clobbering it.","type":"boolean"},"sourcePath":{"description":"Filesystem path of the MIDI map file to bring in. It is COPIED into the user maps directory, so later edits to the original have no effect.","minLength":1,"type":"string"}},"required":["sourcePath"],"type":"object"},"midi.port.role.set":{"additionalProperties":false,"properties":{"port":{"description":"Reported port name, e.g. 'USB MIDI Interface'.","minLength":1,"type":"string"},"role":{"description":"instrument (the DEFAULT): note messages play the selected instrument track and are recordable; the port's note-matched control bindings are suppressed, while its CC/pitch-bend bindings still fire. control: every binding fires and notes never sound.","enum":["instrument","control"],"type":"string"}},"required":["port","role"],"type":"object"},"midi.reload":{"additionalProperties":false,"properties":{},"type":"object"},"mix.eq":{"additionalProperties":false,"properties":{"band":{"description":"v1 channel EQ: 4 bands, index 0-3.","maximum":3,"minimum":0,"type":"integer"},"freqHz":{"description":"Band centre frequency in Hz, 20 to 20000. The four bands start at 80, 250, 2500 and 8000 Hz.","maximum":20000,"minimum":20,"type":"number"},"gainDb":{"description":"Cut or boost for this band in dB, -24 to 24; 0 is flat.","maximum":24,"minimum":-24,"type":"number"},"q":{"description":"Optional bandwidth (resonance): greater than 0, at most 10, higher is narrower. Bands start at 1. OMITTING it leaves the band's stored Q exactly as it was \u2014 it is not reset \u2014 and the inverse then leaves Q alone too.","exclusiveMinimum":0,"maximum":10,"type":"number"},"trackId":{"description":"Id of the track whose channel EQ changes.","minLength":1,"type":"string"}},"required":["trackId","band","freqHz","gainDb"],"type":"object"},"mix.gain":{"additionalProperties":false,"properties":{"gainDb":{"description":"Channel fader in dB, -60 to 12; 0 is unity. The bound is enforced by the executor, not only by this schema.","maximum":12,"minimum":-60,"type":"number"},"trackId":{"description":"Id of the track whose channel fader moves.","minLength":1,"type":"string"}},"required":["trackId","gainDb"],"type":"object"},"mix.limiter.set":{"additionalProperties":false,"properties":{"ceilingDb":{"default":-1,"description":"Optional output ceiling in dBFS, -6 to 0. A new project starts at -1; OMITTING this leaves the stored ceiling exactly as it was rather than resetting it.","maximum":0,"minimum":-6,"type":"number"},"enabled":{"description":"true engages the master limiter, false bypasses it. Absolute, not a toggle; a new project starts with it off.","type":"boolean"},"releaseMs":{"default":50,"description":"Optional release time in milliseconds, 1 to 1000. A new project starts at 50; OMITTING this leaves the stored release exactly as it was rather than resetting it.","maximum":1000,"minimum":1,"type":"number"}},"required":["enabled"],"type":"object"},"mix.master.gain":{"additionalProperties":false,"properties":{"gainDb":{"description":"Master fader in dB, -60 to 12; 0 is unity. The bound is enforced by the executor, not only by this schema.","maximum":12,"minimum":-60,"type":"number"}},"required":["gainDb"],"type":"object"},"mix.pan":{"additionalProperties":false,"properties":{"pan":{"description":"Stereo position, -1 is hard left and 1 is hard right; 0 is centre.","maximum":1,"minimum":-1,"type":"number"},"trackId":{"description":"Id of the track whose pan moves.","minLength":1,"type":"string"}},"required":["trackId","pan"],"type":"object"},"mix.send":{"additionalProperties":false,"properties":{"amount":{"description":"Send level, 0 sends nothing and 1 is unity. LINEAR, not dB.","maximum":1,"minimum":0,"type":"number"},"bus":{"description":"Which of the two fixed effect returns to feed: 'a' is the REVERB return, 'b' is the DELAY return. Both sum into master.","enum":["a","b"],"type":"string"},"trackId":{"description":"Id of the track being sent from.","minLength":1,"type":"string"}},"required":["trackId","bus","amount"],"type":"object"},"note.add":{"additionalProperties":false,"properties":{"clipId":{"description":"Id of a NOTE-BACKED clip (one made by clip.placeMidi). Rejected on an audio clip.","minLength":1,"type":"string"},"notes":{"description":"The notes to add, at least one. Each entry carries its own caller-minted noteId plus start, length, pitch and velocity. One call is ONE journal entry, so a whole chord adds and undoes as a unit.","items":{"additionalProperties":false,"properties":{"lengthTicks":{"description":"Sounding length in ticks. Must be > 0.","exclusiveMinimum":0,"type":"integer"},"noteId":{"description":"Note identity, unique within its clip. Minted UI-SIDE (ULID-shaped), exactly like autopoint.add's pointId \u2014 the engine never mints an id at apply time, because a minted id would make replay diverge from the live model.","minLength":1,"type":"string"},"pitch":{"description":"MIDI note number, 0 to 127; 60 is middle C. The engine never clamps \u2014 a batch that would leave the range is refused whole.","maximum":127,"minimum":0,"type":"integer"},"startTicks":{"description":"Clip-relative position in ticks.","minimum":0,"type":"integer"},"velocity":{"description":"MIDI velocity, 0 to 127. Send it as an INTEGER literal: it is journaled as a Num, whose integer/float shape the blake3 chain depends on, so 100 and 100.0 are DIFFERENT wire values that hash differently. The validator does not protect you here \u2014 JSON Schema treats any number with a zero fractional part as an integer, so 100.0 is accepted and silently journaled with the float shape it arrived in.","maximum":127,"minimum":0,"type":"integer"}},"required":["noteId","startTicks","lengthTicks","pitch","velocity"],"type":"object"},"minItems":1,"type":"array"}},"required":["clipId","notes"],"type":"object"},"note.duplicate":{"additionalProperties":false,"properties":{"clipId":{"description":"Id of the note-backed clip the batch lives in. Rejected on an audio clip.","minLength":1,"type":"string"},"deltaPitch":{"description":"Signed semitone offset applied to the copies, -127 to 127. No clamping: if any copy would leave 0..127 the whole command is refused.","maximum":127,"minimum":-127,"type":"integer"},"deltaTicks":{"description":"Signed time offset applied to the copies.","type":"integer"},"newNoteIds":{"description":"Ids for the copies, positionally paired with noteIds and the same length. Minted UI-side.","items":{"description":"Note identity, unique within its clip. Minted UI-SIDE (ULID-shaped), exactly like autopoint.add's pointId \u2014 the engine never mints an id at apply time, because a minted id would make replay diverge from the live model.","minLength":1,"type":"string"},"minItems":1,"type":"array","uniqueItems":true},"noteIds":{"description":"The batch this command acts on. One chord drag is ONE journal entry, so relative offsets inside the selection are a property of the command rather than the caller's responsibility.","items":{"description":"Note identity, unique within its clip. Minted UI-SIDE (ULID-shaped), exactly like autopoint.add's pointId \u2014 the engine never mints an id at apply time, because a minted id would make replay diverge from the live model.","minLength":1,"type":"string"},"minItems":1,"type":"array","uniqueItems":true}},"required":["clipId","noteIds","newNoteIds","deltaTicks","deltaPitch"],"type":"object"},"note.move":{"additionalProperties":false,"properties":{"clipId":{"description":"Id of the note-backed clip the batch lives in. Rejected on an audio clip.","minLength":1,"type":"string"},"deltaPitch":{"description":"Signed semitone offset applied to every note in the batch, -127 to 127. No clamping: if any note would leave 0..127 the whole command is refused.","maximum":127,"minimum":-127,"type":"integer"},"deltaTicks":{"description":"Signed time offset applied to every note in the batch.","type":"integer"},"noteIds":{"description":"The batch this command acts on. One chord drag is ONE journal entry, so relative offsets inside the selection are a property of the command rather than the caller's responsibility.","items":{"description":"Note identity, unique within its clip. Minted UI-SIDE (ULID-shaped), exactly like autopoint.add's pointId \u2014 the engine never mints an id at apply time, because a minted id would make replay diverge from the live model.","minLength":1,"type":"string"},"minItems":1,"type":"array","uniqueItems":true}},"required":["clipId","noteIds","deltaTicks","deltaPitch"],"type":"object"},"note.quantize":{"additionalProperties":false,"properties":{"clipId":{"description":"Id of the note-backed clip the batch lives in. Rejected on an audio clip.","minLength":1,"type":"string"},"gridTicks":{"description":"The grid division to pull toward, in ticks (960 = a quarter at PPQ 960, 240 = a sixteenth). Lines are measured from the project's phaseAnchorTicks, so a song with a lead-in quantizes to its real bar 1 rather than to tick 0.","exclusiveMinimum":0,"type":"integer"},"noteIds":{"description":"The batch this command acts on. REQUIRED and non-empty: there is deliberately no \"quantize the whole clip\" spelling, because quantize is destructive to a performance that was played off the grid on purpose. A caller that means every note enumerates every note.","items":{"description":"Note identity, unique within its clip. Minted UI-SIDE (ULID-shaped), exactly like autopoint.add's pointId \u2014 the engine never mints an id at apply time, because a minted id would make replay diverge from the live model.","minLength":1,"type":"string"},"minItems":1,"type":"array","uniqueItems":true},"quantizeEnds":{"description":"false: only note STARTS move, lengths are preserved exactly. true: the note END is pulled to the same grid at the same strength, so lengths change. Off is the musical default; legato passages get chopped by an ends-quantize.","type":"boolean"},"strengthPercent":{"description":"How far each note travels toward its grid line, as an INTEGER percent. 100 is mechanical; 50-80 tightens the timing while keeping the feel. Integer rather than a 0..1 float because journaled values are Num and the hash chain depends on their integer/float shape (0.8 and 80 are not interchangeable under canonicalization).","maximum":100,"minimum":0,"type":"integer"}},"required":["clipId","noteIds","gridTicks","strengthPercent","quantizeEnds"],"type":"object"},"note.remove":{"additionalProperties":false,"properties":{"clipId":{"description":"Id of the note-backed clip the notes live in. Rejected on an audio clip.","minLength":1,"type":"string"},"noteIds":{"description":"The batch this command acts on. One chord drag is ONE journal entry, so relative offsets inside the selection are a property of the command rather than the caller's responsibility.","items":{"description":"Note identity, unique within its clip. Minted UI-SIDE (ULID-shaped), exactly like autopoint.add's pointId \u2014 the engine never mints an id at apply time, because a minted id would make replay diverge from the live model.","minLength":1,"type":"string"},"minItems":1,"type":"array","uniqueItems":true}},"required":["clipId","noteIds"],"type":"object"},"note.resize":{"additionalProperties":false,"properties":{"clipId":{"description":"Id of the note-backed clip the batch lives in. Rejected on an audio clip.","minLength":1,"type":"string"},"deltaTicks":{"description":"Signed length/start offset. Positive on the leading edge shortens from the front; positive on the trailing edge lengthens.","type":"integer"},"edge":{"description":"leading moves the note start and shortens by the same amount; trailing changes the length only.","enum":["leading","trailing"],"type":"string"},"noteIds":{"description":"The batch this command acts on. One chord drag is ONE journal entry, so relative offsets inside the selection are a property of the command rather than the caller's responsibility.","items":{"description":"Note identity, unique within its clip. Minted UI-SIDE (ULID-shaped), exactly like autopoint.add's pointId \u2014 the engine never mints an id at apply time, because a minted id would make replay diverge from the live model.","minLength":1,"type":"string"},"minItems":1,"type":"array","uniqueItems":true}},"required":["clipId","noteIds","edge","deltaTicks"],"type":"object"},"note.timing.set":{"additionalProperties":false,"properties":{"clipId":{"description":"Id of the note-backed clip the batch lives in. Rejected on an audio clip.","minLength":1,"type":"string"},"notes":{"description":"One entry per note. Every noteId must be distinct and must already exist in the clip.","items":{"additionalProperties":false,"properties":{"lengthTicks":{"description":"Absolute sounding length in ticks, not a delta. Must be > 0.","exclusiveMinimum":0,"type":"integer"},"noteId":{"description":"An EXISTING note in this clip. This command never creates or removes a note; note.add / note.remove own that.","minLength":1,"type":"string"},"startTicks":{"description":"Absolute clip-relative position, not a delta.","minimum":0,"type":"integer"}},"required":["noteId","startTicks","lengthTicks"],"type":"object"},"minItems":1,"type":"array"}},"required":["clipId","notes"],"type":"object"},"note.velocity.set":{"additionalProperties":false,"properties":{"clipId":{"description":"Id of the note-backed clip the batch lives in. Rejected on an audio clip.","minLength":1,"type":"string"},"deltaVelocity":{"description":"Signed velocity offset applied to every note in the batch, -127 to 127. Integer, so the journaled Num shape is stable by construction. No clamping: if any note would leave 0..127 the whole command is refused.","maximum":127,"minimum":-127,"type":"integer"},"noteIds":{"description":"The batch this command acts on. One chord drag is ONE journal entry, so relative offsets inside the selection are a property of the command rather than the caller's responsibility.","items":{"description":"Note identity, unique within its clip. Minted UI-SIDE (ULID-shaped), exactly like autopoint.add's pointId \u2014 the engine never mints an id at apply time, because a minted id would make replay diverge from the live model.","minLength":1,"type":"string"},"minItems":1,"type":"array","uniqueItems":true}},"required":["clipId","noteIds","deltaVelocity"],"type":"object"},"project.new":{"additionalProperties":false,"properties":{"name":{"description":"Display name for the new project; also the .mstudio package's name on disk. Non-empty. This is a NAME, not a path \u2014 project.open is the one that takes a path.","minLength":1,"type":"string"}},"required":["name"],"type":"object"},"project.open":{"additionalProperties":false,"properties":{"path":{"description":"Filesystem path to an existing .mstudio package directory. Non-empty, and the package must already exist: this command never creates one.","minLength":1,"type":"string"}},"required":["path"],"type":"object"},"project.save":{"additionalProperties":false,"properties":{},"type":"object"},"project.setKey":{"additionalProperties":false,"properties":{"key":{"description":"Key and scale as '<root> <mode>', e.g. 'C major' or 'A minor'. Root is A-G with an optional '#' or 'b'; mode is 'major' or 'minor'. Matches the keyscale vocabulary ace_generator.py already uses. Metadata only \u2014 note content is not checked against it.","pattern":"^[A-G](#|b)? (major|minor)$","type":"string"}},"required":["key"],"type":"object"},"project.setPhaseAnchor":{"additionalProperties":false,"properties":{"anchorTicks":{"description":"Ticks the project bar grid is shifted by, so the first tracked downbeat lands on a bar line without a lead-in. 0 is the v1 behaviour.","minimum":0,"type":"integer"}},"required":["anchorTicks"],"type":"object"},"project.setTempo":{"additionalProperties":false,"properties":{"bpm":{"description":"Tempo in beats per minute, greater than 0 and at most 999. Journaled as a Num, so the integer/float SHAPE is part of the hash chain: send 120, not 120.0, unless you mean a fractional tempo.","exclusiveMinimum":0,"maximum":999,"type":"number"}},"required":["bpm"],"type":"object"},"project.setTimeSig":{"additionalProperties":false,"properties":{"denominator":{"description":"Beat unit \u2014 the BOTTOM number of 4/4 \u2014 one of 1, 2, 4, 8, 16 or 32.","enum":[1,2,4,8,16,32],"type":"integer"},"numerator":{"description":"Beats per bar \u2014 the TOP number of 4/4 \u2014 from 1 to 32.","maximum":32,"minimum":1,"type":"integer"}},"required":["numerator","denominator"],"type":"object"},"publish.track":{"additionalProperties":false,"properties":{"assetHash":{"description":"blake3 hash of the already-exported asset to publish: 64 lowercase hex characters, the same spelling clip.place's assetHash uses.","pattern":"^[0-9a-f]{64}$","type":"string"},"metadata":{"description":"Optional free-form metadata object handed to the publish pipeline unchanged. No shape is enforced here, and this build records it rather than sending it.","type":"object"},"title":{"description":"Title the track is published under. Non-empty.","minLength":1,"type":"string"}},"required":["assetHash","title"],"type":"object"},"record.cancel":{"additionalProperties":false,"properties":{},"type":"object"},"record.inputListen":{"additionalProperties":false,"properties":{"deviceId":{"description":"Optional input device name to open. Omitted opens the system default input.","type":"string"},"enabled":{"description":"true opens the input for metering only (no landing); false closes it. Does not enable speaker monitoring.","type":"boolean"}},"required":["enabled"],"type":"object"},"record.rotate":{"additionalProperties":false,"properties":{},"type":"object"},"record.start":{"additionalProperties":false,"properties":{"deviceId":{"description":"Optional input device name to open. Omitted opens the system default input.","type":"string"},"punchOutTicks":{"description":"Punch-out position. When set, record.stop lands a clip of exactly punchOutTicks minus startTicks (the punch region), truncating or silence-padding the capture to fit. Omitted means open-ended capture until record.stop.","minimum":0,"type":"integer"},"startTicks":{"description":"With punchOutTicks, the punch-in position. Otherwise, when stopped, the position where the take lands after snapping to the anchored bar grid; while rolling without a punch it is ignored. Default: the capture origin.","minimum":0,"type":"integer"},"trackId":{"description":"The armed track to capture onto.","minLength":1,"type":"string"}},"required":["trackId"],"type":"object"},"record.stop":{"additionalProperties":false,"properties":{},"type":"object"},"route.connect":{"additionalProperties":false,"properties":{"edgeId":{"description":"Caller-minted, stable id for the new edge: letters, digits, '_' and '-' only, never '.'. Must not already be in use.","minLength":1,"pattern":"^[A-Za-z0-9_-]+$","type":"string"},"from":{"description":"Source node ref: 'track.<id>', 'bus.<id>' or 'master'.","pattern":"^(master|(track|bus)\\.[A-Za-z0-9_-]+)$","type":"string"},"level":{"description":"Linear send level for the new edge, 0 (silent) to 4; 1 is unity. Linear, not dB.","maximum":4,"minimum":0,"type":"number"},"tap":{"description":"Where the source is tapped: 'pre' (before its fader, so the send is independent of the fader) or 'post' (after it).","enum":["pre","post"],"type":"string"},"to":{"description":"Destination node ref: 'track.<id>', 'bus.<id>' or 'master'.","pattern":"^(master|(track|bus)\\.[A-Za-z0-9_-]+)$","type":"string"}},"required":["edgeId","from","to","level","tap"],"type":"object"},"route.disconnect":{"additionalProperties":false,"properties":{"edgeId":{"description":"Id of the edge to remove. Undo re-creates it with the same level and tap.","minLength":1,"type":"string"}},"required":["edgeId"],"type":"object"},"route.edge.set":{"additionalProperties":false,"properties":{"edgeId":{"description":"Id of an existing edge.","minLength":1,"type":"string"},"level":{"description":"Linear send level, 0 (silent) to 4; 1 is unity. Linear, not dB.","maximum":4,"minimum":0,"type":"number"},"tap":{"description":"Where the source is tapped: 'pre' (before its fader, so the send is independent of the fader) or 'post' (after it, so the fader rides the send too).","enum":["pre","post"],"type":"string"}},"required":["edgeId","level","tap"],"type":"object"},"route.node.add":{"additionalProperties":false,"properties":{"kind":{"description":"What kind of node this is: 'bus' (an aux/effect destination fed by sends) or 'group' (a submix whose members route into it instead of straight to master).","enum":["bus","group"],"type":"string"},"name":{"description":"Display name for the bus or group, e.g. 'Drum Bus'. Non-empty; nodeId, not this, is the wire identity.","minLength":1,"type":"string"},"nodeId":{"description":"Opaque id. Must not contain '.' so node refs stay parseable.","minLength":1,"pattern":"^[A-Za-z0-9_-]+$","type":"string"}},"required":["nodeId","kind","name"],"type":"object"},"route.node.remove":{"additionalProperties":false,"properties":{"nodeId":{"description":"Id of the bus/group node to remove. Every edge touching it is removed too, and undo restores the node with all of them.","minLength":1,"type":"string"}},"required":["nodeId"],"type":"object"},"route.node.set":{"additionalProperties":false,"properties":{"gainDb":{"description":"Node fader in dB, -60 to 12; 0 is unity. When a bus.<nodeId>.gain automation lane exists, the lane value wins for the rendered gain and this is the static fallback.","maximum":12,"minimum":-60,"type":"number"},"nodeId":{"description":"Id of the bus/group node whose fader moves. Track strips and master are not addressable here \u2014 mix.gain and mix.master.gain own those.","minLength":1,"type":"string"}},"required":["nodeId","gainDb"],"type":"object"},"section.remove":{"additionalProperties":false,"properties":{"sectionId":{"description":"Id of an existing section. Removing an id that is not there is a typed error, not a silent no-op.","minLength":1,"type":"string"}},"required":["sectionId"],"type":"object"},"section.set":{"additionalProperties":false,"properties":{"color":{"description":"Optional swatch, '#RRGGBB' hex with six digits and no alpha (e.g. '#FF8800'). Omitted leaves the section with no explicit colour.","pattern":"^#[0-9A-Fa-f]{6}$","type":"string"},"name":{"description":"Section label shown in the arrangement ruler, e.g. 'Verse', 'Chorus', 'Bridge' or 'Drop'. Non-empty.","minLength":1,"type":"string"},"sectionId":{"description":"Caller-minted, stable id for the section; the engine never mints one. A fresh id CREATES a section, an existing id UPDATES it (this command is an upsert).","minLength":1,"type":"string"},"startTicks":{"description":"Where the section begins, in absolute timeline ticks from 0 (PPQ 960: 960 ticks is a quarter note, 3840 is one 4/4 bar).","minimum":0,"type":"integer"}},"required":["sectionId","name","startTicks"],"type":"object"},"studio.importStemSession":{"additionalProperties":false,"properties":{"stemSessionId":{"description":"Id of the Stem Sessions session to bring in. In this build it is used ONLY to mint a placeholder track ('trk_stems_<id>', named 'Stem Session <id>'): no session is looked up, no audio is copied and no clips are created.","minLength":1,"type":"string"}},"required":["stemSessionId"],"type":"object"},"take.auditionMix":{"additionalProperties":false,"properties":{"stems":{"description":"Which stems should be audible: at least one of 'vocals', 'drums', 'bass', 'other', 'mix'. NOT IMPLEMENTED: the executor checks takeId, ignores this list entirely and returns ok with mutated:false. Nothing in the engine stores or reads it, so what you hear does not change.","items":{"enum":["vocals","drums","bass","other","mix"],"type":"string"},"minItems":1,"type":"array"},"takeId":{"description":"Id of the per-stem take being auditioned. Must be a take this project knows.","minLength":1,"type":"string"}},"required":["takeId","stems"],"type":"object"},"take.discard":{"additionalProperties":false,"properties":{"takeId":{"description":"Id of the candidate take to drop from the active list. Its audio stays under takes/ until a purge, so this stays reversible.","minLength":1,"type":"string"}},"required":["takeId"],"type":"object"},"take.promote":{"additionalProperties":false,"properties":{"takeId":{"description":"Id of the candidate take to commit \u2014 the takeId gen.landed reported.","minLength":1,"type":"string"},"targetClipId":{"description":"Clip the take is spliced into; for a new gen.song this may be a clip created as part of promotion.","minLength":1,"type":"string"}},"required":["takeId","targetClipId"],"type":"object"},"take.purge":{"additionalProperties":false,"properties":{"takeId":{"description":"Id of an UN-PROMOTED candidate take to mark offline so its audio can be reclaimed. Manage tier: the tool also needs confirm: true.","minLength":1,"type":"string"}},"required":["takeId"],"type":"object"},"take.restore":{"additionalProperties":false,"properties":{"takeId":{"description":"Id of an offline take to bring back to candidate status. Only the journal state is restored \u2014 the audio may need regeneration before it can be auditioned.","minLength":1,"type":"string"}},"required":["takeId"],"type":"object"},"track.add":{"additionalProperties":false,"properties":{"index":{"description":"Optional 0-based insert position; 0 makes it the first track. May equal the current track count (append), and anything larger is refused. Omitted appends.","minimum":0,"type":"integer"},"name":{"description":"Display name on the track header, e.g. 'Lead Vocal'. Non-empty, need not be unique, and is NOT the identity \u2014 trackId is.","minLength":1,"type":"string"},"trackId":{"description":"Caller-minted, stable id for the new track; the engine never mints one, because a minted id would make replay diverge from the live model. An id already in use is refused, never merged.","minLength":1,"type":"string"}},"required":["trackId","name"],"type":"object"},"track.arm":{"additionalProperties":false,"properties":{"armed":{"description":"true arms the track for recording, false disarms. Absolute, not a toggle. Arming alone never opens the microphone \u2014 record.start or record.inputListen does.","type":"boolean"},"trackId":{"description":"Id of the track to arm. record.start captures onto armed tracks.","minLength":1,"type":"string"}},"required":["trackId","armed"],"type":"object"},"track.mute":{"additionalProperties":false,"properties":{"muted":{"description":"true silences the track in playback and in every bounce, false unmutes it. Absolute, not a toggle.","type":"boolean"},"trackId":{"description":"Id of the track to mute or unmute.","minLength":1,"type":"string"}},"required":["trackId","muted"],"type":"object"},"track.remove":{"additionalProperties":false,"properties":{"trackId":{"description":"Id of the track to delete. Every clip, device, effect, send and automation lane on it goes too, and undo restores all of them.","minLength":1,"type":"string"}},"required":["trackId"],"type":"object"},"track.rename":{"additionalProperties":false,"properties":{"name":{"description":"New display name for the track. Non-empty.","minLength":1,"type":"string"},"trackId":{"description":"Id of the track to rename. The id itself never changes \u2014 it is the wire identity for the life of the project.","minLength":1,"type":"string"}},"required":["trackId","name"],"type":"object"},"track.reorder":{"additionalProperties":false,"properties":{"newIndex":{"description":"0-based destination slot. Must be strictly LESS than the current track count \u2014 unlike track.add's index, which may equal it.","minimum":0,"type":"integer"},"trackId":{"description":"Id of the track to move.","minLength":1,"type":"string"}},"required":["trackId","newIndex"],"type":"object"},"track.setColor":{"additionalProperties":false,"properties":{"color":{"description":"Track colour as '#RRGGBB' hex: six hex digits, leading '#' required, no alpha channel (e.g. '#3AA6FF').","pattern":"^#[0-9A-Fa-f]{6}$","type":"string"},"trackId":{"description":"Id of the track being recoloured.","minLength":1,"type":"string"}},"required":["trackId","color"],"type":"object"},"track.setHeight":{"additionalProperties":false,"properties":{"heightPx":{"description":"Lane height in points, 24 to 400. Purely how tall the lane is drawn; it changes nothing about the audio.","maximum":400,"minimum":24,"type":"integer"},"trackId":{"description":"Id of the track whose lane height changes.","minLength":1,"type":"string"}},"required":["trackId","heightPx"],"type":"object"},"track.setInputChannel":{"additionalProperties":false,"properties":{"channel":{"description":"0-based hardware input channel this track records from: channel 0 is the first input on the interface. On a four-input box, set 0, 1, 2, 3 across four armed tracks and one pass lands each channel on its own track.","minimum":0,"type":"integer"},"trackId":{"description":"Id of the audio track whose hardware input assignment changes.","minLength":1,"type":"string"}},"required":["trackId","channel"],"type":"object"},"track.solo":{"additionalProperties":false,"properties":{"soloed":{"description":"true solos the track (only soloed tracks are heard), false unsolos. Absolute, not a toggle. Honoured by the master bounce and deliberately IGNORED by stem export, which always writes every track.","type":"boolean"},"trackId":{"description":"Id of the track to solo or unsolo.","minLength":1,"type":"string"}},"required":["trackId","soloed"],"type":"object"},"transport.loop.clear":{"additionalProperties":false,"properties":{},"type":"object"},"transport.loop.set":{"additionalProperties":false,"properties":{"endTicks":{"description":"Loop end, in absolute timeline ticks from 0 (PPQ 960: 960 ticks is a quarter note, 3840 is one 4/4 bar). Must be strictly AFTER startTicks.","minimum":0,"type":"integer"},"startTicks":{"description":"Loop start, in absolute timeline ticks from 0 (PPQ 960: 960 ticks is a quarter note, 3840 is one 4/4 bar). Must be strictly BEFORE endTicks; equal or inverted is refused, so a zero-length loop cannot be set.","minimum":0,"type":"integer"}},"required":["startTicks","endTicks"],"type":"object"},"transport.metronome":{"additionalProperties":false,"properties":{"enabled":{"description":"true starts the click, false stops it. Absolute, not a toggle: sending true twice leaves the click on.","type":"boolean"}},"required":["enabled"],"type":"object"},"transport.play":{"additionalProperties":false,"properties":{},"type":"object"},"transport.seek":{"additionalProperties":false,"properties":{"positionTicks":{"description":"Where to put the playhead, in absolute timeline ticks from 0 (PPQ 960: 960 ticks is a quarter note, 3840 is one 4/4 bar). Seeking past the end of the material is al